import React, { useState } from 'react';

function TimeBlock({ id, title, timeRange, icon, period, items = [], onUpdate, hourSlots }) {
  const [isEditing, setIsEditing] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('');
  const [selectedPractice, setSelectedPractice] = useState('');
  const [selectedDuration, setSelectedDuration] = useState('30 мин');
  const [repeatInterval, setRepeatInterval] = useState('');
  const [selectedHour, setSelectedHour] = useState('');

  const categories = [
    {
      name: 'Yoga',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Boxing',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'SoftDev',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'MBA',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'English',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Oratory',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Math',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Chinise',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Finance',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Chess',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    },
    {
      name: 'Business',
      practices: ['Ядро', 'Стандарт 1', 'Стандарт 2', 'Стандарт 3']
    }
  ];

  const timeOptions = [
    '5 мин', '10 мин', '15 мин', '30 мин', '31 мин',
    '60 мин', '90 мин', '120 мин', '180 мин'
  ];

  const repeatOptions = [
    'Не повторять',
    'Каждый день',
    'Каждую неделю',
    'Каждый месяц',
    'Каждый год'
  ];

  const addItem = () => {
    if (selectedCategory && selectedPractice && selectedHour) {
      const newItem = {
        id: Date.now(),
        category: selectedCategory,
        practice: selectedPractice,
        duration: selectedDuration,
        repeat: repeatInterval,
        period: period,
        timeRange: timeRange,
        hour: selectedHour
      };
      onUpdate([...items, newItem]);

      // Сброс формы
      setSelectedCategory('');
      setSelectedPractice('');
      setSelectedDuration('30 мин');
      setRepeatInterval('');
      setSelectedHour('');
      setIsEditing(false);
    }
  };

  const removeItem = (itemId) => {
    onUpdate(items.filter(item => item.id !== itemId));
  };

  const getCategoryColor = (category) => {
    const colors = {
      'Yoga': '#ff6b6b',
      'Boxing': '#4ecdc4',
      'SoftDev': '#45b7d1',
      'MBA': '#96ceb4',
      'English': '#ffeaa7',
      'Oratory': '#ff9ff3',
      'Math': '#feca57',
      'Chinise': '#ffb8b8',
      'Finance': '#c56cf0',
      'Chess': '#ffcccc',
      'Business': '#a8e6cf'
    };
    return colors[category] || '#ddd';
  };

  const getCurrentCategory = () => {
    return categories.find(c => c.name === selectedCategory);
  };

  // Группировка элементов по часам
  const getItemsByHour = () => {
    const grouped = {};
    hourSlots.forEach(hour => {
      grouped[hour] = items.filter(item => item.hour === hour);
    });
    return grouped;
  };

  const itemsByHour = getItemsByHour();

  // Получить фоновый цвет в зависимости от периода
  const getPeriodBackground = () => {
    switch(period) {
      case 'утро': return 'linear-gradient(135deg, #fff9e6, #ffe0b2)';
      case 'день': return 'linear-gradient(135deg, #e6f3ff, #b3e0ff)';
      case 'вечер': return 'linear-gradient(135deg, #e6e6fa, #d1c4e9)';
      default: return 'white';
    }
  };

  return (
    <div
      className="time-block"
      style={{
        borderColor: getCategoryColor(items[0]?.category),
        background: getPeriodBackground()
      }}
    >
      <div className="block-header">
        <span className="block-icon">{icon}</span>
        <h3>{title}</h3>
        <span className="block-time">{timeRange}</span>
      </div>

      <div className="block-content">
        <div className="hours-container">
          {hourSlots.map(hour => (
            <div key={hour} className="hour-group">
              <div className="hour-label">{hour}</div>
              <div className="hour-items">
                {itemsByHour[hour]?.length > 0 ? (
                  itemsByHour[hour].map(item => (
                    <div
                      key={item.id}
                      className="hour-item"
                      style={{ backgroundColor: getCategoryColor(item.category) }}
                      onClick={() => {
                        if (window.confirm('Удалить запись?')) {
                          removeItem(item.id);
                        }
                      }}
                    >
                      <div className="item-category">{item.category}</div>
                      <div className="item-practice">{item.practice}</div>
                      <div className="item-duration">⏱️ {item.duration}</div>
                      {item.repeat && item.repeat !== 'Не повторять' && (
                        <div className="item-repeat">🔄</div>
                      )}
                    </div>
                  ))
                ) : (
                  <div className="empty-hour" onClick={() => {
                    setSelectedHour(hour);
                    setIsEditing(true);
                  }}>
                    +
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>

        {isEditing && (
          <div className="add-item-form">
            <div className="selected-hour">
              Время: <strong>{selectedHour}</strong>
            </div>

            <select
              value={selectedCategory}
              onChange={(e) => {
                setSelectedCategory(e.target.value);
                setSelectedPractice('');
              }}
            >
              <option value="">Выберите категорию</option>
              {categories.map(cat => (
                <option key={cat.name} value={cat.name}>{cat.name}</option>
              ))}
            </select>

            {selectedCategory && (
              <select
                value={selectedPractice}
                onChange={(e) => setSelectedPractice(e.target.value)}
              >
                <option value="">Выберите практику</option>
                {getCurrentCategory()?.practices.map(practice => (
                  <option key={practice} value={practice}>{practice}</option>
                ))}
              </select>
            )}

            <select
              value={selectedDuration}
              onChange={(e) => setSelectedDuration(e.target.value)}
            >
              {timeOptions.map(time => (
                <option key={time} value={time}>{time}</option>
              ))}
            </select>

            <select
              value={repeatInterval}
              onChange={(e) => setRepeatInterval(e.target.value)}
            >
              {repeatOptions.map(option => (
                <option key={option} value={option}>{option}</option>
              ))}
            </select>

            <div className="form-actions">
              <button
                onClick={addItem}
                className="add-btn"
                disabled={!selectedCategory || !selectedPractice || !selectedHour}
              >
                Добавить
              </button>
              <button
                onClick={() => {
                  setIsEditing(false);
                  setSelectedHour('');
                }}
                className="cancel-btn"
              >
                Отмена
              </button>
            </div>
          </div>
        )}

        {!isEditing && items.length === 0 && (
          <div className="block-footer">
            <p className="empty-message">Нет записей. Нажмите на + в нужном часе, чтобы добавить.</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default TimeBlock;
